import base64,datetime,hashlib,json,pathlib
stage=pathlib.Path('/var/tmp/km3-pmp4010-alarm-20261019-735538978204/motion-compare-proposal')
stage.mkdir(mode=0o700,exist_ok=False)
items={'motion_compare_once.py': '', 'pinned_payload.py': ''}
expected={'motion_compare_once.py': 'e530b81f231d3ccccca5df741ccc0f79ec410b9cf5569e517d14428ca7151202', 'pinned_payload.py': 'd8d99ccffdf1b1cb3fc02669af2627243f9801b4fe8861cc39f18692af954a62'}
for name,encoded in items.items():
 raw=base64.b64decode(encoded,validate=True)
 assert hashlib.sha256(raw).hexdigest()==expected[name]
 with (stage/name).open('xb') as stream:stream.write(raw)
 assert hashlib.sha256((stage/name).read_bytes()).hexdigest()==expected[name]
print(json.dumps(dict(event='staged_exact_files',utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),stage=str(stage),sha256=expected)))
